mapper.select:
select userId, userName, nickName, phonenumber, email, avatar, sex, status, deptId, userType,
createBy, createTime, updateBy, updateTime, remark
from sys_user

    delFlag != '1'

      and  userName like concat('%',#{userName},'%')


        and status = #{status}


        and deptId = #{deptId}


        and email = #{email}
